// Development-only build. The caller supplies a byte-verified prior ZIP extraction
// and a runtime generated by the existing development-protected workflow.
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {readFileSync,readdirSync,mkdirSync,writeFileSync} from 'node:fs';
import {join,resolve} from 'node:path';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {verifySource} from './v16-git-chain.mjs';
import {verifyGithubEvidence} from './v16-previous-artifact.mjs';
import {composeDev} from './v16-dev-site.mjs';
import {routes} from './v16-site-overlay.mjs';

const here=fileURLToPath(new URL('.',import.meta.url));
const git=(...a)=>execFileSync('git',a,{maxBuffer:20000000,env:{...process.env,GIT_NO_LAZY_FETCH:'1'}});
const hash=b=>createHash('sha256').update(b).digest('hex');
function walk(root,prefix=''){return Object.fromEntries(readdirSync(root,{withFileTypes:true}).flatMap(x=>{assert(x.isFile()||x.isDirectory(),'SPECIAL_FILE_DENIED');const n=prefix+x.name;return x.isDirectory()?Object.entries(walk(join(root,x.name),n+'/')):[[n,readFileSync(join(root,x.name))]]}));}
function put(root,files){for(const [n,b] of Object.entries(files)){assert(!n.startsWith('/')&&!n.includes('\\')&&!n.split('/').some(x=>!x||x==='.'||x==='..'));const p=join(root,n);mkdirSync(resolve(p,'..'),{recursive:true});writeFileSync(p,b,{flag:'wx'});}}
async function main(){
 const e=process.env;
 assert.equal(e.GITHUB_ACTIONS,'true');assert.equal(e.GITHUB_REPOSITORY,'leisurewang0827/tennis-note-public');
 assert.equal(e.GITHUB_REF,'refs/heads/codex/tennisnote-r4-admin-prod-candidate');assert.equal(e.GITHUB_EVENT_NAME,'push');assert.equal(e.GITHUB_RUN_ATTEMPT,'1');
 assert.equal(e.GITHUB_WORKFLOW_REF,'leisurewang0827/tennis-note-public/.github/workflows/v16-dev-preview.yml@refs/heads/codex/tennisnote-r4-admin-prod-candidate');
 const binding=JSON.parse(readFileSync(join(here,'v16-execution.json'),'utf8'));
 assert.match(binding.sourceCommit||'',/^[a-f0-9]{40}$/,'SOURCE_NOT_BOUND');verifySource(binding.sourceCommit);
 assert.equal(git('rev-parse','HEAD').toString().trim(),e.GITHUB_SHA);assert.equal(git('rev-list','--parents','-n','1',e.GITHUB_SHA).toString().trim(),e.GITHUB_SHA+' '+binding.sourceCommit);
 const root='release-sources/v16-preview';
 const paths=['.github/workflows/v16-dev-preview.yml',...['v16-git-chain.mjs','v16-previous-artifact.mjs','v16-site-overlay.mjs','v16-dev-site.mjs','v16-safe-unpack.py','v16-dev-build.mjs','v16-dev-publish.mjs','v16-execution.json','product-manifest.json','prior-manifest.json','admin-redirects'].map(x=>root+'/'+x)].sort();
 const changed=git('diff-tree','--no-commit-id','--name-only','-r',binding.sourceCommit,e.GITHUB_SHA).toString().trim().split('\n').filter(Boolean).sort();assert.deepEqual(changed,paths,'EXECUTOR_SCOPE_MISMATCH');
 for(const p of paths)assert.deepEqual(readFileSync(p),git('show',e.GITHUB_SHA+':'+p),'EXECUTOR_FILE_DRIFT');
 await verifyGithubEvidence(e.GH_TOKEN);
 const oldBytes=readFileSync(join(here,'prior-manifest.json')),manifest=readFileSync(join(here,'product-manifest.json'));
 const runtime=readFileSync(join(e.RUNNER_TEMP,'absence-runtime/shared/config.local.js')),redirect=readFileSync(join(here,'admin-redirects'));
 const base=join(e.RUNNER_TEMP,'v16-prior-artifact'),out=join(e.RUNNER_TEMP,'v16-dev-sites');
 const result={source:binding.sourceCommit,executor:e.GITHUB_SHA,runId:e.GITHUB_RUN_ID,runtime:'development',sites:{}};
 for(const surface of ['admin','coach']){
  const sourceBytes=Object.fromEntries([...new Set(Object.values(routes[surface]))].map(p=>[p,git('show',binding.sourceCommit+':'+p.slice(7))]));
  const args={surface,seal:JSON.parse(readFileSync(join(base,surface,'seal.json'),'utf8')),files:walk(join(base,surface,'site')),priorManifestBytes:oldBytes,v16ManifestBytes:manifest,sourceBytes};
  const site=composeDev(args,runtime,redirect);put(join(out,surface),site.files);result.sites[surface]=site.hashes;
 }
 writeFileSync(join(out,'seal.json'),JSON.stringify(result)+'\n',{flag:'wx'});
 console.log(JSON.stringify({status:'V16_DEV_BUILD_PASS',admin:182,coach:253,runtime:'development',dbWrites:0}));
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url))await main();
